window.SANTA_STORIES = [{"id": 0, "title": "La estrella que olvidó brillar", "scene": "village", "discovery": "Una estrella diminuta cayó junto a la ventana y pidió ayuda: había olvidado cómo encenderse.", "problem": "Chispa explicó que ninguna estrella encontraba su luz cuando intentaba brillar completamente sola.", "choices": ["Reunir a los vecinos para cantar", "Visitar a quien estaba solo"], "outcomes": ["El canto de la plaza se convirtió en un hilo dorado. La estrella lo siguió y recuperó su resplandor.", "Una taza compartida iluminó una ventana. La estrella comprendió que acompañar a alguien también era una forma de brillar."], "ending": "La estrella volvió al cielo y dejó una promesa: siempre habría luz donde alguien hiciera sitio a los demás."}, {"id": 1, "title": "El reno que tenía miedo de volar", "scene": "reindeer", "discovery": "Un reno joven escondía el arnés. Desde el establo, el cielo parecía demasiado grande.", "problem": "Los demás ya estaban listos. El reno temía equivocarse y necesitaba avanzar a su propio ritmo.", "choices": ["Ensayar con pasos pequeños", "Volar junto a un amigo"], "outcomes": ["Primero dio un salto sobre la nieve, después otro. Cada intento le enseñó algo y el miedo se hizo más pequeño.", "Un amigo voló a su lado, sin apresurarlo. Juntos encontraron un ritmo tranquilo entre las nubes."], "ending": "No fue el vuelo más rápido, pero sí el más valiente. Ser valiente también es pedir compañía."}, {"id": 2, "title": "La carta sin dirección", "scene": "correo", "discovery": "Lumi encontró una carta sin dirección. Dentro solo decía: «Quiero que alguien me escuche».", "problem": "No había nombre ni calle. Santa decidió que aquella carta merecía tanta atención como cualquier otra.", "choices": ["Buscar pistas en el dibujo", "Preguntar con amabilidad en la plaza"], "outcomes": ["En el borde había un puente azul dibujado. Bajo aquel puente encontraron una casa y a alguien esperando una visita.", "Los vecinos recordaron una casa silenciosa al final del camino. Fueron juntos a saludar y a escuchar."], "ending": "La mejor respuesta no llegó envuelta. Fue una conversación larga, sin prisas, junto a una taza caliente."}, {"id": 3, "title": "El tren de las galletas", "scene": "village", "discovery": "El tren de Bruno transportaba galletas para compartir cuando una rueda se hundió en la nieve.", "problem": "Las galletas debían llegar tibias a la plaza. Empujar sin organizarse solo enterraba más el vagón.", "choices": ["Construir un pequeño camino", "Descargar y repartir entre todos"], "outcomes": ["Tilo colocó tablas sobre la nieve. Una a una, las ruedas avanzaron por el camino nuevo.", "Cada vecino llevó una cesta. Al llegar a la plaza, el tren estaba vacío y las mesas, llenas."], "ending": "Bruno descubrió que llegar juntos era más importante que llegar en tren. Nadie se quedó sin galleta."}, {"id": 4, "title": "El regalo invisible", "scene": "cabin", "discovery": "Santa mostró una caja que parecía vacía. Sin embargo, la cinta brillaba cada vez que alguien era amable.", "problem": "Tilo buscó dentro con una lupa, pero no encontró ningún juguete. ¿Qué regalo podía no verse?", "choices": ["Escuchar a un amigo", "Ayudar sin esperar premio"], "outcomes": ["Una amistad necesitaba tiempo para contar una preocupación. Escuchar con atención hizo que la cinta brillara como el sol.", "Ordenaron el taller en silencio para que los duendes descansaran. La caja se llenó de una luz tranquila."], "ending": "Dentro estaba el tiempo regalado a los demás. No se podía tocar, pero todos pudieron sentirlo."}, {"id": 5, "title": "La campana de los buenos deseos", "scene": "village", "discovery": "La campana de la plaza dejó de sonar justo cuando iba a empezar la celebración.", "problem": "Nina leyó una inscripción: «Solo canto cuando los deseos también piensan en otros».", "choices": ["Desear compañía para todos", "Desear un bosque cuidado"], "outcomes": ["Los vecinos abrieron sus puertas y alargaron las mesas. La campana respondió con una nota clara.", "Recogieron las cintas y los papeles del bosque. La campana dejó escapar un tintineo suave."], "ending": "Los deseos se convirtieron en acciones. Y la campana sonó, porque alguien había empezado a cumplirlos."}, {"id": 6, "title": "Un puente de luces", "scene": "village", "discovery": "El puente que unía dos barrios perdió sus faroles durante una ventisca.", "problem": "A ambos lados esperaban familias que querían reunirse. Cruzar a oscuras no era una buena idea.", "choices": ["Reparar los faroles con Tilo", "Esperar juntos y compartir linternas"], "outcomes": ["Trabajando con cuidado, Tilo fijó los faroles. Una hilera cálida volvió a dibujar el camino.", "Reunieron linternas y esperaron a que la ventisca terminara. Después un adulto comprobó el puente y los acompañó."], "ending": "Cada luz recordó una mano que había ayudado. La paciencia también había construido aquel puente."}, {"id": 7, "title": "La fábrica de copos de nieve", "scene": "cabin", "discovery": "En un rincón del taller había una máquina que creaba copos de papel para decorar ventanas.", "problem": "Tilo estaba preocupado: ninguno salía exactamente igual al anterior. Pensaba que todos estaban mal hechos.", "choices": ["Comparar sus hermosas diferencias", "Decorar una ventana con todos"], "outcomes": ["Miraron cada dibujo con atención. Unos tenían puntas largas, otros pequeñas estrellas, y todos eran bonitos.", "En la ventana, los copos distintos formaron el paisaje más alegre de la aldea. Ninguno sobraba."], "ending": "Tilo dejó de buscar copos idénticos. Aprendió que las diferencias podían hacer más hermoso el conjunto."}, {"id": 8, "title": "El muñeco de nieve sin bufanda", "scene": "village", "discovery": "En la plaza había un muñeco de nieve con sombrero, botones y una sonrisa, pero sin bufanda.", "problem": "Nina tenía una bufanda guardada. Antes de decorar al muñeco, vio a un vecino temblando junto a la puerta.", "choices": ["Abrigar primero al vecino", "Preparar una bufanda de papel para el muñeco"], "outcomes": ["El vecino recibió la bufanda de lana. Con retazos de colores hicieron otra, de adorno, para el muñeco.", "El muñeco estrenó una alegre bufanda de papel. La de lana quedó libre para quien necesitaba calor."], "ending": "La plaza estaba preciosa, pero lo más bonito fue comprobar que nadie seguía pasando frío."}, {"id": 9, "title": "La biblioteca de los abrazos", "scene": "cabin", "discovery": "En la gran biblioteca apareció un libro cuyas páginas se llenaban cuando alguien cuidaba a otra persona.", "problem": "El libro de aquella noche seguía en blanco. Santa propuso escribir una historia con gestos pequeños.", "choices": ["Ofrecer un abrazo preguntando primero", "Enviar un mensaje cariñoso"], "outcomes": ["Preguntaron si alguien quería un abrazo. Quien lo deseó recibió uno, y las páginas se iluminaron.", "Escribieron mensajes para las personas que estaban lejos. Las páginas recogieron cada palabra de cariño."], "ending": "El libro no exigía un mismo gesto a todos. Cada persona podía compartir afecto a su manera."}, {"id": 10, "title": "El saco de las pequeñas ayudas", "scene": "mirador", "discovery": "El bolso rojo de Santa se había vuelto pesado, aunque dentro solo había una pizca de estrellas.", "problem": "Cada chispa guardaba una tarea pendiente de la aldea. Santa no podía hacerlas todas solo.", "choices": ["Ayudar en la oficina de cartas", "Ayudar a ordenar los juguetes"], "outcomes": ["Separaron las cartas con cuidado para que Lumi encontrara cada destino. El bolso empezó a pesar menos.", "Ordenaron las piezas y comprobaron que nada faltara. Tilo sonrió y varias chispas subieron al cielo."], "ending": "El bolso quedó ligero. Muchas ayudas pequeñas habían conseguido algo que parecía enorme."}, {"id": 11, "title": "La noche de las ventanas encendidas", "scene": "village", "discovery": "Una calle estaba decorada con muchas luces, salvo la última casa, cuya ventana permanecía oscura.", "problem": "Los vecinos pensaron que allí no querían celebrar. Santa sugirió preguntar antes de sacar conclusiones.", "choices": ["Llamar con una invitación amable", "Dejar una cesta y una nota"], "outcomes": ["La familia estaba cuidando a alguien enfermo. Agradeció una visita breve y encendió una lámpara junto a la ventana.", "La nota decía que podían unirse cuando quisieran. Más tarde, una pequeña luz respondió desde dentro."], "ending": "No todas las casas celebran igual. Aquella noche aprendieron a invitar sin exigir y a acompañar con respeto."}, {"id": 12, "title": "El mapa de las sonrisas", "scene": "correo", "discovery": "Lumi encontró un mapa sin calles. Solo tenía puntos dorados que aparecían por toda la aldea.", "problem": "Santa explicó que el mapa registraba momentos de cariño, pero faltaba una zona entera junto al molino.", "choices": ["Visitar el molino", "Invitar al molinero a la plaza"], "outcomes": ["El molinero llevaba días trabajando solo. Se sentaron a conversar mientras terminaba su tarea.", "Alguien lo ayudó a cerrar a tiempo. En la plaza lo esperaba un lugar y una taza caliente."], "ending": "Un punto dorado apareció junto al molino. No era un tesoro escondido: era una nueva amistad."}, {"id": 13, "title": "El taller de juguetes reparados", "scene": "cabin", "discovery": "Tilo encontró un oso de tela con una costura abierta y un tren con una rueda suelta.", "problem": "Los juguetes nuevos brillaban al otro lado del taller, pero estos todavía podían acompañar muchas aventuras.", "choices": ["Coser el oso con ayuda", "Revisar el tren con Tilo"], "outcomes": ["Una aguja manejada por Tilo cerró la costura. Después añadieron un lazo que parecía una pequeña medalla.", "Tilo ajustó la rueda y comprobó el movimiento. El tren volvió a recorrer la mesa sin detenerse."], "ending": "Reparar también era regalar. Los juguetes tenían nuevas historias por delante y menos cosas acabaron en la basura."}, {"id": 14, "title": "Rodolfo y la luz compartida", "scene": "reindeer", "discovery": "La nariz de Rodolfo brillaba sobre el camino, pero detrás del establo quedaba un rincón oscuro.", "problem": "Rodolfo no podía iluminar todas las puertas a la vez. Necesitaba compartir la tarea con la aldea.", "choices": ["Repartir faroles seguros", "Formar un camino con luces"], "outcomes": ["Santa repartió faroles que no quemaban. Cada vecino iluminó un pequeño tramo y el camino apareció.", "Tilo colocó luces protegidas a lo largo de la cerca. Rodolfo siguió el sendero y encontró la puerta."], "ending": "Su luz seguía siendo especial. Compartida con otras, llegaba mucho más lejos."}, {"id": 15, "title": "La estrella sobre el campanario", "scene": "village", "discovery": "Una estrella de adorno quedó atrapada en lo alto del campanario durante la decoración.", "problem": "Chispa quiso trepar solo, pero Santa recordó que había que buscar una forma segura y pedir ayuda.", "choices": ["Llamar a quienes reparan la torre", "Crear otra estrella para la plaza"], "outcomes": ["Los encargados cerraron el paso y usaron su equipo. Más tarde devolvieron la estrella a su sitio.", "Mientras llegaba la ayuda, hicieron una estrella nueva con papel. La espera se convirtió en un taller alegre."], "ending": "La celebración continuó sin riesgos. Pedir ayuda había sido la decisión más inteligente de la noche."}, {"id": 16, "title": "La receta de Nina", "scene": "cabin", "discovery": "Nina preparaba galletas para todos cuando descubrió que le faltaba un ingrediente.", "problem": "Sin aquel ingrediente la receta cambiaría. Nina temía que ya nadie quisiera probar sus galletas.", "choices": ["Inventar una receta nueva", "Preguntar si podían compartir ingredientes"], "outcomes": ["Midieron de nuevo con ayuda y crearon galletas diferentes, pequeñas y crujientes. La cocina olía a aventura.", "Una vecina llevó lo que faltaba y se quedó a cocinar. Pronto hubo dos delantales trabajando juntos."], "ending": "La mejor parte de la receta fue compartir la mesa. También explicaron los ingredientes antes de ofrecer las galletas."}, {"id": 17, "title": "El buzón de los agradecimientos", "scene": "correo", "discovery": "Al lado del buzón de deseos apareció otro más pequeño: era el buzón de los agradecimientos.", "problem": "Lumi lo abrió y lo encontró vacío. Todos habían pedido algo, pero pocos habían pensado en dar las gracias.", "choices": ["Escribir a alguien de la familia", "Agradecer una ayuda cotidiana"], "outcomes": ["La primera nota recordó las veces que alguien había escuchado con paciencia. Pronto llegaron muchas más.", "Una carta agradeció al barrendero su trabajo. Otra recordó a quien había arreglado una puerta rota."], "ending": "El buzón pequeño terminó lleno. Agradecer hizo visibles muchas cosas buenas que antes pasaban inadvertidas."}, {"id": 18, "title": "El secreto del lago helado", "scene": "village", "discovery": "Desde la orilla del lago se veía una luz bajo el hielo. Parecía una estrella perdida.", "problem": "El hielo no era un lugar para jugar. Santa pidió observar desde el sendero y mantener la distancia.", "choices": ["Mirar con los prismáticos", "Buscar el reflejo desde la orilla"], "outcomes": ["Con los prismáticos descubrieron una lámpara en la casa de enfrente. Su reflejo brillaba sobre el agua.", "Al caminar por la orilla segura, la luz se movió con ellos. Era un reflejo, no un objeto atrapado."], "ending": "Habían resuelto un misterio sin acercarse al hielo. La curiosidad y el cuidado podían ir de la mano."}, {"id": 19, "title": "El cascabel que sonaba bajito", "scene": "reindeer", "discovery": "Un cascabel del trineo sonaba tan suave que casi no se escuchaba entre los demás.", "problem": "El reno que lo llevaba pensó que no servía para la gran salida y quiso esconderlo.", "choices": ["Escuchar todos en silencio", "Darle un turno en la canción"], "outcomes": ["Cuando la aldea guardó silencio, apareció una nota delicada y hermosa. Siempre había estado allí.", "Entre dos campanadas fuertes dejaron un pequeño espacio. El cascabel suave completó la melodía."], "ending": "No hacía falta sonar más fuerte para ser valioso. A veces bastaba con que los demás aprendieran a escuchar."}, {"id": 20, "title": "La Navidad que llegó en una carta", "scene": "correo", "discovery": "Una carta de otra ciudad describía una Navidad cálida, sin nieve, con música junto a una ventana abierta.", "problem": "Tilo pensaba que no podía haber Navidad sin muñecos de nieve. La carta le hizo muchas preguntas.", "choices": ["Responder contando su celebración", "Preparar una mesa con costumbres distintas"], "outcomes": ["Escribieron sobre sus faroles y preguntaron por las canciones de aquella familia. Pronto tuvieron un intercambio de historias.", "Cada vecino llevó una tradición de su hogar. La mesa quedó llena de sabores y recuerdos diferentes."], "ending": "No había una sola manera de celebrar. Lo que compartían era el deseo de estar cerca y tratarse con cariño."}, {"id": 21, "title": "El bosque de las promesas pequeñas", "scene": "bosque", "discovery": "En el bosque aparecieron cintas de papel con promesas muy grandes que nadie sabía cómo cumplir.", "problem": "Santa propuso empezar con algo pequeño, concreto y posible, en vez de prometerlo todo de una vez.", "choices": ["Cuidar un rincón del bosque", "Ayudar cada día con una tarea"], "outcomes": ["Recogieron los papeles del sendero y dejaron el lugar limpio. La primera promesa ya estaba cumplida.", "Eligieron una tarea sencilla y la anotaron. Al terminarla, dibujaron una estrella junto al día."], "ending": "El bosque no cambió de golpe. Pero cada gesto repetido hizo que aquella promesa creciera de verdad."}, {"id": 22, "title": "El reloj de la Nochebuena", "scene": "cabin", "discovery": "El reloj del taller se detuvo cuando todos corrían de una tarea a otra sin mirarse.", "problem": "Nadie sabía si faltaba mucho o poco. Bruno propuso parar, respirar y ordenar lo que quedaba por hacer.", "choices": ["Organizar las tareas entre todos", "Tomar un pequeño descanso"], "outcomes": ["Cada duende eligió una tarea y pidió ayuda si la necesitaba. El taller dejó de parecer una carrera.", "Se sentaron a beber agua y a revisar la lista. Después regresaron más tranquilos y atentos."], "ending": "Tilo reparó el reloj, pero la lección ya estaba aprendida: hacer una pausa también ayuda a avanzar."}, {"id": 23, "title": "La caja de los buenos recuerdos", "scene": "cabin", "discovery": "Santa abrió una caja llena de objetos sencillos: una pluma, una cinta y un dibujo doblado.", "problem": "Tilo buscó un objeto caro. Santa sonrió y preguntó qué historia guardaba cada pequeña cosa.", "choices": ["Añadir un dibujo de una buena tarde", "Guardar una nota para alguien querido"], "outcomes": ["El dibujo recordó una tarde de juegos compartidos. Al mirarlo, todos pudieron volver un momento a ella.", "La nota contaba algo bonito que no querían olvidar. La doblaron con cuidado y la guardaron juntos."], "ending": "La caja se hizo más valiosa sin monedas. Guardaba los momentos que daban calor al corazón."}, {"id": 24, "title": "La bufanda que unió la aldea", "scene": "village", "discovery": "Nina empezó a tejer una bufanda, pero se quedó sin lana antes de terminarla.", "problem": "Cada vecino tenía un ovillo distinto. Ninguno alcanzaba por sí solo para completar el trabajo.", "choices": ["Combinar todos los colores", "Hacer varias bufandas pequeñas"], "outcomes": ["Unieron colores diferentes hasta crear una bufanda larguísima. Cada franja contaba quién había colaborado.", "Prepararon piezas pequeñas y las regalaron a quienes las necesitaban. Cada una llevaba una tarjeta cariñosa."], "ending": "El resultado no era igual al primer plan, pero abrigaba mucho más: todos habían puesto algo de sí."}, {"id": 25, "title": "El jardín de las luces amables", "scene": "village", "discovery": "Chispa diseñó un jardín de luces para que todos pudieran recorrerlo al caer la tarde.", "problem": "Al probarlo, descubrió que algunos pasos eran estrechos y otras luces deslumbraban demasiado.", "choices": ["Escuchar a quienes lo visitarían", "Cambiar el camino y las luces"], "outcomes": ["Las ideas de los vecinos ayudaron a crear pasos amplios, bancos y luces suaves. El jardín empezó a ser de todos.", "Tilo ensanchó el camino y protegió las luces. Dejaron también un rincón tranquilo para descansar."], "ending": "La magia del jardín no estaba en tener más luces, sino en que cada persona pudiera disfrutarlo a su manera."}, {"id": 26, "title": "El pequeño guardián del trineo", "scene": "reindeer", "discovery": "Antes de salir, Santa encontró a un reno joven vigilando el trineo con mucha seriedad.", "problem": "El pequeño creía que debía resolver cualquier problema sin molestar a nadie. Entonces vio una correa suelta.", "choices": ["Avisar a Santa", "Pedir una revisión a Tilo"], "outcomes": ["Santa agradeció el aviso y revisó el arnés antes de empezar. Hablar a tiempo había sido una gran ayuda.", "Tilo revisó las correas una por una y aseguró la pieza. El reno observó para aprender."], "ending": "Cuidar del trineo no significaba hacerlo todo solo. Un buen guardián sabía cuándo pedir ayuda."}, {"id": 27, "title": "La noche en que todos fueron invitados", "scene": "village", "discovery": "La plaza tenía una gran mesa preparada, pero algunas sillas estaban vacías al empezar la fiesta.", "problem": "No todos conocían la invitación. Otros pensaban que debían llevar un regalo para poder participar.", "choices": ["Ir a invitar puerta por puerta", "Poner un cartel de bienvenida"], "outcomes": ["Explicaron que bastaba con querer compartir un rato. Nuevas familias llegaron con historias y sonrisas.", "El cartel aclaró que todos podían sentarse sin traer regalos. Las sillas se fueron llenando poco a poco."], "ending": "Alargaron la mesa una vez más. La celebración creció cuando dejaron de contar los paquetes y empezaron a contar a las personas."}, {"id": 28, "title": "El último deseo del año", "scene": "mirador", "discovery": "Santa encontró un deseo pequeño al fondo del bolso, justo cuando la aldea se preparaba para un año nuevo.", "problem": "Decía: «Que lo bueno de esta noche no termine mañana». Nadie sabía cómo guardar una celebración entera.", "choices": ["Elegir una buena acción para mañana", "Hacer un calendario de pequeños gestos"], "outcomes": ["Decidieron empezar el día visitando a alguien y ayudando con una tarea. El deseo ya tenía un primer paso.", "Dibujaron doce casillas y escribieron gestos posibles: escuchar, compartir, agradecer y cuidar. No necesitaban esperar otra Navidad."], "ending": "El año nuevo no llegó con una promesa perfecta, sino con ganas de volver a intentarlo cada día."}, {"id": 29, "title": "El nombre escrito en las estrellas", "scene": "mirador", "discovery": "Santa sostuvo una pizca de polvo de estrellas sobre su pequeño bolso rojo. En cada destello había un recuerdo amable.", "problem": "Para que el cielo mostrara un nombre, primero debían recordar una buena acción, por pequeña que pareciera.", "choices": ["Recordar un gesto de ayuda", "Recordar una palabra cariñosa"], "outcomes": ["Recordaron una mano tendida en un momento difícil. La pizca empezó a subir formando un hilo dorado.", "Recordaron una palabra que había devuelto una sonrisa. Los destellos comenzaron a girar despacio."], "ending": "El cielo dibujó el nombre de quien escuchaba el cuento. Santa sonrió: cada persona podía dejar una luz bonita en el mundo."}];
window.SANTA_BOOKS = [{"id": 0, "title": "La aldea nevada", "kind": "house"}, {"id": 1, "title": "Los renos de Santa", "kind": "reindeer"}, {"id": 2, "title": "El taller de juguetes", "kind": "gift"}, {"id": 3, "title": "La estrella viajera", "kind": "star"}, {"id": 4, "title": "Santa y sus cartas", "kind": "santa"}, {"id": 5, "title": "El tren de Navidad", "kind": "train"}, {"id": 6, "title": "Los amigos del bosque", "kind": "snowman"}, {"id": 7, "title": "El árbol de los deseos", "kind": "tree"}, {"id": 8, "title": "La cocina de Nina", "kind": "cookie"}, {"id": 9, "title": "Los duendes sin barba", "kind": "elf"}];
